#include <stdio.h>
#include <string.h>

#define MAXN 100005
#define LOG 17
#define BSZ 320
#define MAXB ((MAXN + BSZ - 1) / BSZ + 1)

static char ibuf[1 << 16];
static int ipos = 0, ilen = 0;
static inline int gc(void) {
    if (ipos == ilen) {
        ilen = (int)fread(ibuf, 1, sizeof(ibuf), stdin);
        ipos = 0;
        if (ilen <= 0) return -1;
    }
    return ibuf[ipos++];
}
static inline int readInt(void) {
    int c = gc();
    while (c != -1 && (c < '0' || c > '9')) c = gc();
    int x = 0;
    while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = gc(); }
    return x;
}

static char obuf[1 << 21];
static int opos = 0;
static inline void writeIntLn(int x) {
    char tmp[12];
    int n = 0;
    if (x == 0) tmp[n++] = '0';
    while (x > 0) { tmp[n++] = (char)('0' + x % 10); x /= 10; }
    while (n) obuf[opos++] = tmp[--n];
    obuf[opos++] = '\n';
}

static int par[MAXN];
static int dep[MAXN];        /* profundidade na arvore original */
static int tin_[MAXN], tout_[MAXN];
static int up[LOG][MAXN];
static int cstart[MAXN + 2], clist[MAXN];
static int stk_[MAXN], ci[MAXN], fp[MAXN + 2], cnt[MAXN];

/* profundidade atual: range assign (subarvore), point query */
static int eltT[MAXN], eltV[MAXN];
static int blkT[MAXB], blkV[MAXB];

static inline int pointQ(int pos) {
    int b = pos / BSZ;
    return eltT[pos] >= blkT[b] ? eltV[pos] : blkV[b];
}
static inline void rangeAssign(int l, int r, int val, int t) {
    int bl = l / BSZ, br = r / BSZ;
    if (bl == br) {
        for (int i = l; i <= r; i++) { eltT[i] = t; eltV[i] = val; }
        return;
    }
    int e = (bl + 1) * BSZ;
    for (int i = l; i < e; i++) { eltT[i] = t; eltV[i] = val; }
    for (int b = bl + 1; b < br; b++) { blkT[b] = t; blkV[b] = val; }
    int s = br * BSZ;
    for (int i = s; i <= r; i++) { eltT[i] = t; eltV[i] = val; }
}

static inline int jump(int v, int k) {
    for (int j = 0; k; j++, k >>= 1)
        if (k & 1) v = up[j][v];
    return v;
}

int main(void) {
    int N = readInt();
    for (int i = 2; i <= N; i++) par[i] = readInt();
    par[1] = 1;

    for (int i = 2; i <= N; i++) cnt[par[i]]++;
    cstart[1] = 0;
    for (int u = 1; u <= N; u++) cstart[u + 1] = cstart[u] + cnt[u];
    for (int u = 1; u <= N; u++) fp[u] = cstart[u];
    for (int i = 2; i <= N; i++) clist[fp[par[i]]++] = i;

    /* DFS iterativo (preorder): tin, tout, dep */
    int timer = 0, top = 0;
    stk_[0] = 1;
    tin_[1] = timer++;
    dep[1] = 0;
    ci[1] = cstart[1];
    while (top >= 0) {
        int u = stk_[top];
        if (ci[u] < cstart[u + 1]) {
            int c = clist[ci[u]++];
            tin_[c] = timer++;
            dep[c] = dep[u] + 1;
            ci[c] = cstart[c];
            stk_[++top] = c;
        } else {
            tout_[u] = timer - 1;
            top--;
        }
    }

    /* binary lifting na arvore original */
    for (int v = 1; v <= N; v++) up[0][v] = par[v];
    for (int j = 1; j < LOG; j++)
        for (int v = 1; v <= N; v++)
            up[j][v] = up[j - 1][up[j - 1][v]];

    /* estrutura de profundidade atual */
    for (int v = 1; v <= N; v++) { eltT[tin_[v]] = 0; eltV[tin_[v]] = dep[v]; }
    int nb = (N + BSZ - 1) / BSZ;
    for (int b = 0; b < nb; b++) { blkT[b] = 0; blkV[b] = 0; }

    int Q = readInt();
    for (int op = 1; op <= Q; op++) {
        int type = readInt();
        if (type == 2) {
            int v = readInt();
            int d = pointQ(tin_[v]);
            int l = tin_[v] + 1, r = tout_[v];
            if (l <= r) rangeAssign(l, r, d + 1, op);
        } else {
            int v = readInt(), k = readInt();
            int target = pointQ(tin_[v]) - k;
            if (target < 0) target = 0;
            /* ao longo da cadeia de ancestrais original, D e nao-crescente;
               o ancestral atual com profundidade "target" e o primeiro
               (a partir de v, subindo) cujo D <= target */
            int lo = 0, hi = dep[v];
            while (hi - lo > 1) {
                int mid = (lo + hi) >> 1;
                int w = jump(v, mid);
                if (pointQ(tin_[w]) <= target) hi = mid; else lo = mid;
            }
            writeIntLn(jump(v, hi));
        }
    }
    fwrite(obuf, 1, opos, stdout);
    return 0;
}
